+// Splits CSV text into rows of fields (RFC 4180: quoted fields, "" escapes, CRLF).
+function parseCsv(text) {
+  const rows = [];
+  let row = [];
+  let field = "";
+  let quoted = false;
+  for (let i = 0; i < text.length; i++) {
+    const c = text[i];
+    if (quoted) {
+      if (c === '"' && text[i + 1] === '"') {
+        field += c;
+        i++;
+      } else if (c === '"') quoted = false;
+      else field += c;
+    } else if (c === '"') quoted = true;
+    else if (c === ",") {
+      row.push(field);
+      field = "";
+    } else if (c === "\n" || c === "\r") {
+      if (c === "\r" && text[i + 1] === "\n") i++;
+      row.push(field);
+      rows.push(row);
+      row = [];
+      field = "";
+    } else field += c;
+  }
+  if (field !== "" || row.length) {
+    row.push(field);
+    rows.push(row);
+  }
+  return rows.filter((r) => r.length > 1 || r[0] !== "");
+}
+
+// Reads data/stock.csv as { sku, name, qty, unit, shelf } objects in file order.
+async function readStock() {
+  const [header, ...rows] = parseCsv(await readFile(STOCK_CSV, "utf8"));
+  return rows.map((r) => {
+    const rec = Object.fromEntries(header.map((h, i) => [h.trim(), r[i] ?? ""]));
+    return {
+      sku: rec.sku,
+      name: rec.name,
+      qty: Number(rec.qty),
+      unit: rec.unit === "" ? null : rec.unit,
+      shelf: rec.shelf,
+    };
+  });
+}

